program='''from collections import Counter

def bbox_cells(a, color=None):
    pts=[(r,c) for r,row in enumerate(a) for c,v in enumerate(row) if v!=0 and (color is None or v==color)]
    if not pts: return None
    return min(r for r,c in pts),min(c for r,c in pts),max(r for r,c in pts)+1,max(c for r,c in pts)+1

def crop(a,box):
    r0,c0,r1,c1=box
    return [row[c0:c1] for row in a[r0:r1]]

def converted_stamp(p, marker=None):
    counts=Counter(v for row in p for v in row if v)
    if len(counts)>=2:
        base=min(counts,key=lambda c:(counts[c],-c))
        other=next(c for c in counts if c!=base)
    else:
        base=next(iter(counts)); other=marker
    return [[base if v==0 or v!=base else other for v in row] for row in p]

def paste_stamp(out,stamp,top,left):
    h=len(stamp); w=len(stamp[0])
    for r in range(h):
        for c in range(w):
            rr=top+r; cc=left+c
            if 0<=rr<len(out) and 0<=cc<len(out[0]): out[rr][cc]=stamp[r][c]

def transform(grid):
    h=len(grid); w=len(grid[0]); div=next(c for c in range(w) if all(grid[r][c]==6 for r in range(h)))
    hs=next(r for r in range(h) if all(v==6 for v in grid[r][:div+1]))
    right=[row[div+1:] for row in grid]
    top=[row[:div] for row in grid[:hs]]
    nz=[r for r in range(hs) if any(top[r])]
    gaps=[r for r in range(min(nz)+1,hs) if not any(top[r]) and any(any(top[rr]) for rr in range(r+1,hs))]
    split=gaps[-1] if gaps else hs
    pb=bbox_cells(top[:split]); mb=bbox_cells([row[:] for row in (top[split:]+[[0]*div]*(hs-split))]) if False else None
    pts=[(r,c) for r in range(split,hs) for c in range(div) if top[r][c]]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)+1; c0=min(c for r,c in pts); c1=max(c for r,c in pts)+1
    p=crop(top,pb); m=[row[c0:c1] for row in top[r0:r1]]; mc=top[r0][c0]
    stamp=converted_stamp(p); ph=len(stamp); pw=len(stamp[0])
    touches_left=c0==0; touches_bottom=r1==hs
    if touches_left and touches_bottom:
        m=[row[::-1] for row in m[::-1]]; oy=len(right)-len(m)*ph; ox=len(right[0])-len(m[0])*pw
    elif touches_left:
        m=[list(row) for row in zip(*m[::-1])]; oy=0; ox=len(right[0])-len(m[0])*pw
    elif touches_bottom:
        m=[list(row) for row in zip(*m)][::-1]; oy=len(right)-len(m)*ph; ox=0
    else: oy=ox=0
    # A second stamp is used by a matching map embedded in the right panel.
    embedded=[(r,c) for r in range(hs) for c in range(div+1,w) if grid[r][c]==mc]
    if embedded and hs<h-1:
        er0=min(r for r,c in embedded); er1=max(r for r,c in embedded)+1
        ec0=min(c for r,c in embedded)-div-1; ec1=max(c for r,c in embedded)-div
        em=[row[ec0:ec1] for row in right[er0:er1]][::-1]
        em=[row[::-1] for row in em]
        bottom=[row[:div] for row in grid[hs+1:]]
        bp=bbox_cells(bottom)
        bpat=crop(bottom,bp)
        marker=next((v for row in bottom[bp[2]:] for v in row if v not in (0,6)),7)
        bs=converted_stamp(bpat,marker)
        for r,row in enumerate(em):
            for c,v in enumerate(row):
                if v: paste_stamp(right,bs,er0-(len(bs)-1)+r*len(bs),ec0-(len(bs[0])-1)+c*len(bs[0]))
    for r,row in enumerate(m):
        for c,v in enumerate(row):
            if v: paste_stamp(right,stamp,oy+r*ph,ox+c*pw)
    if embedded:
        for r,c in embedded: right[r][c-div-1]=mc
    return right
'''
